package ar.com.lamontana.archivos;

import static ar.com.lamontana.cotizaciones.PreparacionClienteStore.*;
import ar.com.lamontana.cotizaciones.PreparacionClienteStore;
import java.io.*;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

/** Reutiliza almacenamiento, antivirus, inspector y aceptación de PDF; no acredita ni imprime. */
@Service
public class ArchivoPreparadoService {
    private final PreparacionClienteStore store;private final org.springframework.jdbc.core.JdbcTemplate jdbc;
    private final TransactionTemplate tx;private final ArchivosPrivados storage;private final Antivirus antivirus;private final InspectorPdf inspector;
    public ArchivoPreparadoService(PreparacionClienteStore store,PlatformTransactionManager manager,ArchivosPrivados storage,Antivirus antivirus,InspectorPdf inspector,org.springframework.jdbc.core.JdbcTemplate jdbc){this.store=store;this.jdbc=jdbc;tx=new TransactionTemplate(manager);this.storage=storage;this.antivirus=antivirus;this.inspector=inspector;}
    public ArchivoService.Archivo archivo(UUID prep,UUID file,String correo){var d=store.datos(prep,correo,false);var rows=jdbc.query("SELECT a.*,p.retirado_en,CASE WHEN v.tipo_registro='VISTA_PREVIA' THEN v.fecha END AS aceptada FROM lamontana.archivo_preparado p JOIN lamontana.archivo_almacenado a USING(id_archivo_almacenado) LEFT JOIN lamontana.aceptacion_vista_previa v USING(id_archivo_almacenado) WHERE p.id_preparacion=? AND a.codigo_publico=?",(r,n)->new ArchivoService.Archivo(file,file,r.getString("nombre_original"),r.getString("estado"),r.getTimestamp("retirado_en")==null&&d.estado().equals("ABIERTA"),r.getTimestamp("fecha_creacion").toInstant(),r.getTimestamp("cargar_hasta").toInstant(),r.getObject("cantidad_bytes",Long.class),r.getString("sha256"),r.getObject("cantidad_paginas",Integer.class),r.getString("codigo_resultado"),r.getString("mensaje"),r.getTimestamp("aceptada")==null?null:r.getTimestamp("aceptada").toInstant(),r.getTimestamp("retirado_en")!=null||!d.estado().equals("ABIERTA")),d.id(),file);if(rows.isEmpty())throw error(HttpStatus.NOT_FOUND,"El PDF no pertenece a este trabajo.");return rows.get(0);}
    public List<ArchivoService.Archivo> lista(UUID prep,String correo){var d=store.datos(prep,correo,false);return jdbc.query("SELECT a.codigo_publico FROM lamontana.archivo_preparado p JOIN lamontana.archivo_almacenado a USING(id_archivo_almacenado) WHERE p.id_preparacion=? AND p.retirado_en IS NULL ORDER BY a.id_archivo_almacenado",(r,n)->r.getObject(1,UUID.class),d.id()).stream().map(id->archivo(prep,id,correo)).toList();}
    public ArchivoService.Vista vista(UUID prep,String correo){var d=store.datos(prep,correo,false);var items=lista(prep,correo).stream().map(f->new ArchivoService.Item(f.codigoPublico(),f.nombre(),List.of(f),d.estado().equals("ABIERTA"))).toList();return new ArchivoService.Vista(prep,"Preparación privada",new ArchivoService.Acceso(d.estado().equals("ABIERTA"),"Podés abrir tus PDF cuando quieras. La vista previa es opcional; la producción requiere aprobación y las condiciones de pago."),items,d.version(),null);}
    public ArchivoService.Archivo crear(UUID prep,UUID operacion,String nombre,String correo){return tx.execute(s->{store.bloquear();var d=store.datos(prep,correo,true);nombreSeguro(nombre);var prev=jdbc.query("SELECT a.codigo_publico,p.id_preparacion,a.nombre_original FROM lamontana.archivo_almacenado a LEFT JOIN lamontana.archivo_preparado p USING(id_archivo_almacenado) WHERE a.id_operacion=?",(r,n)->new Object[]{r.getObject(1,UUID.class),r.getObject(2,Long.class),r.getString(3)},operacion);if(!prev.isEmpty()){var p=prev.get(0);if(!Objects.equals(p[1],d.id())||!nombre.strip().equals(p[2]))throw conflicto("Operación de carga ya utilizada.");return archivo(prep,(UUID)p[0],correo);}
        if(lista(prep,correo).size()>=20)throw conflicto("Un trabajo admite hasta 20 PDF; quitá los que no utilices.");
        if(jdbc.queryForObject("SELECT count(*) FROM lamontana.archivo_almacenado WHERE id_usuario_cargador=? AND fecha_creacion>clock_timestamp()-interval '1 hour'",Integer.class,d.usuario())>=60)throw error(HttpStatus.TOO_MANY_REQUESTS,"Se alcanzó el límite de cargas por hora.");
        UUID file=UUID.randomUUID();long id=jdbc.queryForObject("INSERT INTO lamontana.archivo_almacenado(codigo_publico,id_usuario_cargador,id_operacion,nombre_original,estado,cargar_hasta) VALUES (?,?,?,?,'PENDIENTE',clock_timestamp()+interval '10 minutes') RETURNING id_archivo_almacenado",Long.class,file,d.usuario(),operacion,nombre.strip());jdbc.update("INSERT INTO lamontana.archivo_preparado(id_archivo_almacenado,id_preparacion) VALUES (?,?)",id,d.id());store.cambio(d.id(),true);store.evento(d,operacion,"INICIAR_PDF",nombre.strip(),Map.of("archivo",file));return archivo(prep,file,correo);
    });}
    public ArchivoService.Archivo recibir(UUID prep,UUID file,String correo,InputStream input,long length){boolean start=Boolean.TRUE.equals(tx.execute(s->{store.bloquear();store.datos(prep,correo,true);var f=archivo(prep,file,correo);if(!f.activo())throw conflicto("El PDF fue retirado.");if(!f.estado().equals("PENDIENTE"))return false;if(!Instant.now().isBefore(f.cargarHasta()))throw conflicto("La carga venció; quitá el intento e iniciá otro.");if(length>ArchivosPrivados.MAX_BYTES)throw error(HttpStatus.PAYLOAD_TOO_LARGE,"Máximo 10 MiB por PDF.");jdbc.update("UPDATE lamontana.archivo_almacenado SET estado='VALIDANDO',fecha_inicio=clock_timestamp() WHERE codigo_publico=?",file);return true;}));if(!start)return archivo(prep,file,correo);
        String motor=null,stage="SEGURIDAD";
        try{var recibido=storage.recibir(file,input);motor=antivirus.analizar(recibido.path());stage="ESTRUCTURA_RENDER";int paginas=inspector.inspeccionar(recibido.path(),storage.carpeta(file).resolve("inspeccion.txt"));storage.publicar(file);final String version=motor;
            return tx.execute(s->{store.bloquear();var d=store.datos(prep,correo,true);var f=archivo(prep,file,correo);if(!f.activo()||!f.estado().equals("VALIDANDO"))throw conflicto("La carga cambió durante el análisis.");jdbc.update("UPDATE lamontana.archivo_almacenado SET estado='VALIDO',fecha_fin=clock_timestamp(),cantidad_bytes=?,sha256=?,cantidad_paginas=?,codigo_resultado='PDF_PREPARADO',mensaje='PDF analizado y listo. Podés abrir la vista previa si querés comprobar su contenido.' WHERE codigo_publico=?",recibido.bytes(),recibido.sha256(),paginas,file);validar(file,"SEGURIDAD","ACEPTADO","ClamAV",version,"LIMPIO");validar(file,"ESTRUCTURA_RENDER","ACEPTADO","Apache PDFBox","3.0.8","TODAS_LAS_PAGINAS");store.cambio(d.id(),true);store.evento(d,UUID.randomUUID(),"PDF_VALIDADO",file,Map.of("archivo",file,"paginas",paginas,"sha256",recibido.sha256()));return archivo(prep,file,correo);});
        }catch(Exception ex){boolean rechazado=ex instanceof InspectorPdf.Rechazado;String code=rechazado?((InspectorPdf.Rechazado)ex).codigo:ex instanceof InspectorPdf.NoDisponible?"ANALISIS_NO_DISPONIBLE":"CARGA_INTERRUMPIDA";String mensaje=rechazado||ex instanceof InspectorPdf.NoDisponible?ex.getMessage():"La carga se interrumpió. Quitá el intento y volvé a cargar el PDF.";final String v=motor,paso=stage;
            tx.executeWithoutResult(s->{store.bloquear();int n=jdbc.update("UPDATE lamontana.archivo_almacenado SET estado=?,fecha_fin=clock_timestamp(),codigo_resultado=?,mensaje=? WHERE codigo_publico=? AND estado='VALIDANDO'",rechazado?"RECHAZADO":"FALLIDO",code,mensaje,file);if(n==1){if(v!=null)validar(file,"SEGURIDAD","ACEPTADO","ClamAV",v,"LIMPIO");validar(file,paso,rechazado?"RECHAZADO":"INCOMPLETO",paso.equals("SEGURIDAD")?"ClamAV":"Apache PDFBox",paso.equals("SEGURIDAD")?"No disponible":"3.0.8",code);}});try{storage.descartar(file);}catch(IOException ignored){}return archivo(prep,file,correo);
        }
    }
    public ArchivoService.Archivo aceptar(UUID prep,UUID file,UUID operacion,String hash,String correo){return tx.execute(s->{store.bloquear();var d=store.datos(prep,correo,true);var f=archivo(prep,file,correo);if(!f.activo()||!f.estado().equals("VALIDO")||!Objects.equals(f.sha256(),hash))throw conflicto("Sólo se acepta un PDF vigente e inspeccionado.");var prev=store.previo(d,operacion,"ACEPTAR_PDF",List.of(file,hash));if(prev!=null)return f;if(f.aceptadaEn()!=null)return f;try{storage.original(file,hash,f.bytes());}catch(IOException e){throw conflicto("No se pudo comprobar la integridad del PDF.");}jdbc.update("INSERT INTO lamontana.aceptacion_vista_previa(id_archivo_almacenado,id_usuario,id_operacion,sha256) SELECT id_archivo_almacenado,?,?,? FROM lamontana.archivo_almacenado WHERE codigo_publico=?",d.usuario(),operacion,hash,file);store.cambio(d.id(),false);store.evento(d,operacion,"ACEPTAR_PDF",List.of(file,hash),Map.of("archivo",file));return archivo(prep,file,correo);});}
    public void quitar(UUID prep,UUID file,UUID operacion,String correo){tx.executeWithoutResult(s->{store.bloquear();var d=store.datos(prep,correo,true);if(store.previo(d,operacion,"QUITAR_PDF",file)!=null)return;var f=archivo(prep,file,correo);if(f.estado().equals("VALIDANDO"))throw conflicto("Esperá el resultado del análisis antes de quitar el PDF.");jdbc.update("UPDATE lamontana.archivo_preparado SET retirado_en=coalesce(retirado_en,clock_timestamp()) WHERE id_preparacion=? AND id_archivo_almacenado=(SELECT id_archivo_almacenado FROM lamontana.archivo_almacenado WHERE codigo_publico=?)",d.id(),file);store.cambio(d.id(),true);store.evento(d,operacion,"QUITAR_PDF",file,Map.of("archivo",file,"acceso","REVOCADO"));});}
    public ArchivoService.Contenido contenido(UUID prep,UUID file,Integer pagina,String correo){var f=archivo(prep,file,correo);exigirContenido(f);if(pagina!=null&&(pagina<1||pagina>f.paginas()))throw error(HttpStatus.BAD_REQUEST,"Página inválida.");try{Path original=storage.original(file,f.sha256(),f.bytes());if(pagina==null){var bytes=Files.readAllBytes(original);exigirContenido(archivo(prep,file,correo));return new ArchivoService.Contenido(bytes,"application/pdf",f.nombre());}Path out=storage.carpeta(file).resolve("preview-"+UUID.randomUUID()+".png");try{inspector.preview(original,out,pagina-1);var bytes=Files.readAllBytes(out);exigirContenido(archivo(prep,file,correo));return new ArchivoService.Contenido(bytes,"image/png","pagina-"+pagina+".png");}finally{Files.deleteIfExists(out);}}catch(IOException e){throw error(HttpStatus.SERVICE_UNAVAILABLE,"No pudimos recuperar el PDF privado.");}}
    private void exigirContenido(ArchivoService.Archivo f){if(f.revocado())throw error(HttpStatus.GONE,"Este acceso de preparación fue revocado. Consultá los archivos desde el pedido si ya lo creaste.");if(!f.estado().equals("VALIDO"))throw conflicto("El archivo todavía no tiene una inspección segura.");}
    private void nombreSeguro(String nombre){if(nombre==null||nombre.strip().length()>255||!nombre.strip().toLowerCase(Locale.ROOT).endsWith(".pdf")||nombre.codePoints().anyMatch(c->Character.isISOControl(c)||c=='/'||c=='\\'))throw error(HttpStatus.BAD_REQUEST,"Indicá un nombre de PDF sin rutas ni caracteres de control.");}
    private void validar(UUID file,String tipo,String resultado,String motor,String version,String codigo){jdbc.update("INSERT INTO lamontana.validacion_archivo(id_archivo_almacenado,tipo_validacion,resultado,motor,version_motor,codigo_resultado) SELECT id_archivo_almacenado,?,?,?,?,? FROM lamontana.archivo_almacenado WHERE codigo_publico=?",tipo,resultado,motor,version,codigo,file);}
}
